@font-face {
  font-family: 'Syne';
  src: url('/fonts/syne-800.woff2') format('woff2');
  font-weight: 800;
  font-display: swap;
}

:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --text: #1d1f24;
  --muted: #5d6470;
  --accent: #0b7a75;
  --skeleton: #dcdfe4;
  --display: 'Syne', Arial, sans-serif;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--text);
  background: var(--bg);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

.site-header {
  padding: 16px 24px;
  background: var(--surface);
  border-bottom: 1px solid #e3e3df;
}

.logo {
  font-family: var(--display);
  font-weight: 800;
  font-size: 20px;
}

main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
}

h1 {
  font-family: var(--display);
  font-weight: 800;
  font-size: 32px;
  margin: 8px 0 24px;
}

.promo {
  margin: 0 0 16px;
  padding: 16px;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

.card {
  background: var(--surface);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.08);
}

.card-media img {
  display: block;
  width: 100%;
}

.card-body {
  padding: 14px 16px 18px;
}

.card-title {
  font-family: var(--display);
  font-weight: 800;
  font-size: 18px;
  line-height: 1.3;
  margin: 0 0 6px;
}

.card-blurb {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.4;
  margin: 0 0 12px;
  min-height: 2.8em;
}

.card-price {
  font-family: var(--display);
  font-weight: 800;
  font-size: 22px;
  line-height: 1.2;
  margin: 0;
}

.skeleton {
  height: 140px;
  border-radius: 12px;
  background: var(--skeleton);
}

.site-footer {
  max-width: 1100px;
  margin: 32px auto 0;
  padding: 32px 24px 48px;
  border-top: 1px solid #e3e3df;
}

.site-footer h2 {
  font-family: var(--display);
  font-weight: 800;
  font-size: 22px;
  margin: 0 0 8px;
}

.site-footer p {
  color: var(--muted);
  margin: 0 0 16px;
}

.site-footer a {
  color: var(--accent);
  font-weight: 600;
}
